//! Polygenic risk scores for six cancers from genome-wide significant GWAS loci.
//!
//! The loci live in `data/prs_catalog.tsv`, generated by
//! `validation/prs_catalog.py`: GRCh38 positions, alleles and 1000 Genomes
//! phase 3 European (EUR) allele frequencies from Ensembl; risk alleles, odds
//! ratios and PubMed IDs from the NHGRI-EBI GWAS Catalog (p ≤ 5×10⁻⁸).
//!
//! For a disease with loci i, weights βᵢ = ln ORᵢ and risk-allele dosages dᵢ
//! taken from the first sample's GT, the score is S = Σ βᵢ dᵢ. Sites missing
//! from the VCF are taken as homozygous reference, which holds for germline
//! whole-genome call sets but not for somatic, exome or panel VCFs. Under
//! Hardy–Weinberg equilibrium with EUR risk-allele frequencies pᵢ,
//! E[S] = Σ 2pᵢβᵢ and Var[S] = Σ 2pᵢ(1 − pᵢ)βᵢ², and z = (S − E[S]) / √Var[S].
//! These handful of loci explain a small fraction of heritability: the score is
//! a research illustration, not a clinical risk estimate.

use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

use crate::types::VariantRecord;

const CATALOG_TSV: &str = include_str!("../data/prs_catalog.tsv");

/// One GWAS locus for one disease.
#[derive(Debug, Clone)]
struct GwasLocus {
    rsid: String,
    chrom: String,
    pos: u64,
    ref_allele: String,
    alt_allele: String,
    /// True when the risk allele is the reference allele.
    risk_is_ref: bool,
    ln_or: f64,
    /// EUR frequency of the risk allele.
    risk_freq: f64,
    disease: String,
    genes: String,
}

fn catalog() -> &'static [GwasLocus] {
    static CATALOG: OnceLock<Vec<GwasLocus>> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let mut lines = CATALOG_TSV.lines().filter(|l| !l.starts_with('#'));
        let header: Vec<&str> = lines.next().expect("catalog header").split('\t').collect();
        let col = |name: &str| header.iter().position(|h| *h == name).expect(name);
        let (rsid, chrom, pos, r, a) = (
            col("rsid"),
            col("chrom"),
            col("pos"),
            col("ref"),
            col("alt"),
        );
        let (risk_is_ref, or, freq) = (col("risk_is_ref"), col("odds_ratio"), col("eur_risk_freq"));
        let (disease, genes) = (col("disease"), col("genes"));
        lines
            .filter(|l| !l.trim().is_empty())
            .map(|l| {
                let f: Vec<&str> = l.split('\t').collect();
                GwasLocus {
                    rsid: f[rsid].to_string(),
                    chrom: f[chrom].to_string(),
                    pos: f[pos].parse().expect("pos"),
                    ref_allele: f[r].to_string(),
                    alt_allele: f[a].to_string(),
                    risk_is_ref: f[risk_is_ref] == "1",
                    ln_or: f[or].parse::<f64>().expect("odds_ratio").ln(),
                    risk_freq: f[freq].parse().expect("eur_risk_freq"),
                    disease: f[disease].to_string(),
                    genes: f[genes].to_string(),
                }
            })
            .collect()
    })
}

/// PRS result for a single disease.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrsResult {
    /// Disease category.
    pub disease: String,
    /// Polygenic score S = Σ ln(OR) × risk-allele dosage (NaN without genotypes).
    pub raw_score: f64,
    /// Expected score in the EUR reference population, Σ 2p ln(OR).
    #[serde(default)]
    pub expected_score: f64,
    /// (S − E[S]) / SD[S] under Hardy–Weinberg equilibrium (NaN without genotypes).
    pub z_score: f64,
    /// "HIGH" (z > 1.5), "ABOVE_AVERAGE" (0.5 < z ≤ 1.5), "AVERAGE" (−0.5 ≤ z ≤ 0.5),
    /// "BELOW_AVERAGE" (z < −0.5) or "INSUFFICIENT_DATA" (VCF without genotypes).
    pub risk_class: String,
    /// Number of catalogue loci observed in the VCF.
    pub n_variants_matched: usize,
    /// Number of catalogue loci for this disease.
    pub n_variants_total: usize,
    /// Loci carrying at least one risk allele: (rsid, genes, ln OR × dosage).
    pub matched_variants: Vec<(String, String, f64)>,
    /// Caveats about the inputs behind this score.
    #[serde(default)]
    pub note: Option<String>,
}

fn normalize_chrom(chrom: &str) -> String {
    chrom
        .strip_prefix("chr")
        .unwrap_or(chrom)
        .to_ascii_uppercase()
}

/// Compute polygenic risk scores for every disease in the catalogue.
pub fn compute_prs(variants: &[VariantRecord]) -> Vec<PrsResult> {
    use std::collections::HashMap;

    let genotyped = variants.iter().any(|v| v.dosage.is_some());
    let mut by_site: HashMap<(String, u64), Vec<&VariantRecord>> = HashMap::new();
    for v in variants {
        by_site
            .entry((normalize_chrom(&v.chrom), v.pos))
            .or_default()
            .push(v);
    }

    let mut diseases: Vec<&str> = catalog().iter().map(|l| l.disease.as_str()).collect();
    diseases.sort_unstable();
    diseases.dedup();

    let mut results: Vec<PrsResult> = diseases
        .into_iter()
        .map(|disease| {
            let loci: Vec<&GwasLocus> = catalog().iter().filter(|l| l.disease == disease).collect();
            let expected: f64 = loci.iter().map(|l| 2.0 * l.risk_freq * l.ln_or).sum();
            let variance: f64 = loci
                .iter()
                .map(|l| 2.0 * l.risk_freq * (1.0 - l.risk_freq) * l.ln_or * l.ln_or)
                .sum();

            let mut score = 0.0;
            let mut matched = 0usize;
            let mut carriers = Vec::new();
            for l in &loci {
                let observed = by_site
                    .get(&(normalize_chrom(&l.chrom), l.pos))
                    .and_then(|recs| {
                        recs.iter().find(|v| {
                            v.ref_allele.eq_ignore_ascii_case(&l.ref_allele)
                                && v.alt_allele.eq_ignore_ascii_case(&l.alt_allele)
                        })
                    });
                if observed.is_some() {
                    matched += 1;
                }
                // Alternate-allele dosage; absent sites are homozygous reference.
                let alt_dosage = observed.and_then(|v| v.dosage).unwrap_or(0) as f64;
                let risk_dosage = if l.risk_is_ref {
                    2.0 - alt_dosage
                } else {
                    alt_dosage
                };
                if risk_dosage > 0.0 {
                    let contribution = l.ln_or * risk_dosage;
                    score += contribution;
                    carriers.push((l.rsid.clone(), l.genes.clone(), contribution));
                }
            }

            if !genotyped {
                return PrsResult {
                    disease: disease.to_string(),
                    raw_score: f64::NAN,
                    expected_score: expected,
                    z_score: f64::NAN,
                    risk_class: "INSUFFICIENT_DATA".to_string(),
                    n_variants_matched: matched,
                    n_variants_total: loci.len(),
                    matched_variants: Vec::new(),
                    note: Some(
                        "VCF has no sample genotypes (GT); a polygenic score needs a genotyped \
                         germline VCF"
                            .to_string(),
                    ),
                };
            }
            let z = (score - expected) / variance.sqrt();
            let risk_class = if z > 1.5 {
                "HIGH"
            } else if z > 0.5 {
                "ABOVE_AVERAGE"
            } else if z >= -0.5 {
                "AVERAGE"
            } else {
                "BELOW_AVERAGE"
            };
            let note = (matched < loci.len()).then(|| {
                format!(
                    "{} of {} loci absent from the VCF and assumed homozygous reference \
                     (valid only for germline whole-genome calls)",
                    loci.len() - matched,
                    loci.len()
                )
            });
            PrsResult {
                disease: disease.to_string(),
                raw_score: score,
                expected_score: expected,
                z_score: z,
                risk_class: risk_class.to_string(),
                n_variants_matched: matched,
                n_variants_total: loci.len(),
                matched_variants: carriers,
                note,
            }
        })
        .collect();

    results.sort_by(|a, b| {
        b.z_score
            .partial_cmp(&a.z_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.disease.cmp(&b.disease))
    });
    results
}

#[cfg(test)]
mod tests {
    use super::*;

    fn genotyped(chrom: &str, pos: u64, r: &str, a: &str, dosage: u8) -> VariantRecord {
        let mut v = VariantRecord::biallelic(chrom, pos, r, a, 50.0, None, None);
        v.dosage = Some(dosage);
        v
    }

    #[test]
    fn catalog_loads_with_valid_entries() {
        let cat = catalog();
        assert!(cat.len() >= 20);
        for l in cat {
            assert!(l.ln_or > 0.0, "{}: risk allele must have OR > 1", l.rsid);
            assert!(l.risk_freq > 0.0 && l.risk_freq < 1.0, "{}", l.rsid);
            assert_ne!(l.ref_allele, l.alt_allele);
        }
    }

    #[test]
    fn sites_only_vcf_gives_insufficient_data() {
        let v = VariantRecord::biallelic("8", 127401060, "G", "T", 50.0, None, None);
        for r in compute_prs(&[v]) {
            assert_eq!(r.risk_class, "INSUFFICIENT_DATA");
            assert!(r.z_score.is_nan());
        }
    }

    #[test]
    fn dosage_and_risk_orientation_are_respected() {
        // rs16892766 (8:116618444 A>C): risk allele C is the ALT, OR 1.26.
        // rs6983267  (8:127401060 G>T): risk allele G is the REF, OR 1.16.
        let crc = |vs: &[VariantRecord]| {
            compute_prs(vs)
                .into_iter()
                .find(|r| r.disease == "Colorectal cancer")
                .unwrap()
        };
        let base = crc(&[genotyped("1", 1, "A", "G", 1)]);
        let alt_risk = crc(&[
            genotyped("chr8", 116618444, "A", "C", 2),
            genotyped("1", 1, "A", "G", 1),
        ]);
        assert!((alt_risk.raw_score - base.raw_score - 2.0 * 1.26f64.ln()).abs() < 1e-12);
        assert_eq!(alt_risk.n_variants_matched, 1);
        // Homozygous ALT at a REF-risk locus removes its two risk copies.
        let ref_risk = crc(&[
            genotyped("8", 127401060, "G", "T", 2),
            genotyped("1", 1, "A", "G", 1),
        ]);
        assert!((base.raw_score - ref_risk.raw_score - 2.0 * 1.16f64.ln()).abs() < 1e-12);
    }

    #[test]
    fn z_score_uses_hardy_weinberg_moments() {
        let r = compute_prs(&[genotyped("1", 1, "A", "G", 1)]);
        for res in &r {
            let loci: Vec<_> = catalog()
                .iter()
                .filter(|l| l.disease == res.disease)
                .collect();
            let var: f64 = loci
                .iter()
                .map(|l| 2.0 * l.risk_freq * (1.0 - l.risk_freq) * l.ln_or.powi(2))
                .sum();
            let z = (res.raw_score - res.expected_score) / var.sqrt();
            assert!((res.z_score - z).abs() < 1e-12);
        }
    }
}
